			dw kw_goto_ifzero_n, var_fr, if17_1

			; Main.bas 139: If Ready(front) Then t = front
			dw p_ready_c, var_front
			dw kw_goto_ifzero_n, var_ready_ready, if18_1
			dw kw_vtov, var_front, var_runnext_t
if18_1:

			; Main.bas 140: End If
if17_1:

