ntc_rg422:
str61:			db " (HELP)", 0
ntc_rg422_e:
			IF ($ < 32768) && (ntc_rg423_e - ntc_rg423 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
