ntc_rg428:
; ============================================================
; Keyword library (rom)
; ============================================================

; Library: ROM - the keyword library is in the ROM NTC CPCFW (NTCFW.ROM).
; Its routines: this jump block, the numbers made into addresses by the ROM at the start.
; Its variables and constants: fixed addresses (RAM #8800 - #A5EF is the ROM's).
ntc_rj_block:
kw_stop:		jp 1
ntc_xn:		jp 2
kw_goto_iffalse_n:	jp 11
kw_goto_iftrue_n:	jp 13
kw_goto_ifzero_n:	jp 15
kw_forupv_n:	jp 25
kw_next1v_n:	jp 33
kw_ltov:		jp 47
kw_vtov:		jp 48
kw_ztov:		jp 49
kw_ftov:		jp 50
kw_inc:		jp 51
kw_add:		jp 53
kw_addl:		jp 54
kw_subvv:	jp 55
kw_4x:		jp 58
kw_mulvl:	jp 61
kw_divvv:	jp 63
kw_divvl:	jp 64
kw_andvv:	jp 72
kw_andvl:	jp 73
kw_orvv:		jp 74
kw_orvl:		jp 75
kw_notv:		jp 78
kw_scpltvl:	jp 80
kw_scplevv:	jp 81
kw_scplevl:	jp 82
kw_scpgtvv:	jp 83
kw_scpgtvl:	jp 84
kw_scpgevl:	jp 86
kw_cpeqvv:	jp 95
kw_cpeqvl:	jp 96
kw_cpnevv:	jp 97
kw_cpnevl:	jp 98
kw_aget:		jp 111
kw_aset:		jp 112
kw_asetl:	jp 117
kw_strcpy:	jp 122
kw_strcat:	jp 124
kw_strlen:	jp 125
kw_strcmpeq:	jp 126
kw_strcmpne:	jp 127
kw_printstrvar:	jp 129
kw_printint:	jp 131
kw_printnl0:	jp 134
kw_printnl:	jp 138
kw_inkey:	jp 144
kw_cls:		jp 147
kw_model:	jp 150
kw_frame:	jp 152
kw_ticks:	jp 154
kw_strleft:	jp 156
kw_strright:	jp 157
kw_strmid:	jp 173
kw_strstr:	jp 176
kw_strspace:	jp 178
kw_strucase:	jp 180
kw_strtrim:	jp 184
kw_strval:	jp 186
kw_strinstr:	jp 187
kw_l_mov:	jp 206
mem_go0:		jp 243
mem_go:		jp 245
mem_readbyte:	jp 254
mem_writebyte:	jp 256
mem_writeword:	jp 257
mem_freepages:	jp 260
mem_selpage:	jp 268
ntc_isl_tick:	jp 287
kw_bssinit:	jp 288
ntc_plat_irqon:	jp 314
mem_bankcount:	jp 329
mem_allocbank:	jp 330
ntc_kdown:	jp 334
kw_waitkey:	jp 348
NTC_RJ_N	equ 75		; entries
mem_a1	equ #884F		; ROM data
mem_a2	equ #8851		; ROM data
mem_res	equ #8855		; ROM data
ntc_csp	equ #8800		; ROM data
ntc_irqv	equ #8917		; ROM data
ntc_isl	equ #9786		; ROM bss
ntc_isldue	equ #8908		; ROM data
ntc_isln	equ #8907		; ROM data
ntc_nmode	equ #8807		; ROM data
ntc_rampt	equ #881F		; ROM data
ntc_v_free	equ #894E		; ROM data
ntc_v_romen	equ #8954		; ROM data
ntc_v_romold	equ #8956		; ROM data
ntc_v_stamp	equ #8952		; ROM data
ntc_v_start	equ #8950		; ROM data
			ASSERT ntc_free <= #8800, "Library: ROM - the program and its arrays must end below #8800 (the ROM's RAM)"

; End: the caller's ROM selection again, then back to the caller
ntc_rj_exit:
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT
			ret
ntc_rj_old:		dw 0			; the caller's ROM selection (C) and state (B)


; the start code (Library: ROM): run once, then the arrays go over it
ntc_rj_drop:
; the start: find the ROM set in slots 0 - 31 (its main ROM, then the others with the same
; stamp), have the main one patch the jump block. NC = ready; C = not there / too old
; (the message is shown, the caller's ROM selection is back)
ntc_rj_find:
			ld c, 0
			call #B90F		; KL ROM SELECT: B / C = the caller's state and selection
			ld (ntc_rj_old), bc
			xor a
			ld (ntc_rj_want), a
			call ntc_rj_scan		; the main ROM
			jp c, ntc_rj_nf
			ld (ntc_rj_slots), a
			ld e, (hl)
			inc hl
			ld d, (hl)			; its patcher
			ld (ntc_rj_call + 1), de
			ld a, 1
ntc_rj_more:				; the other ROMs of the set
			ld (ntc_rj_want), a
			ld hl, ntc_rj_n
			cp (hl)
			jr nc, ntc_rj_all
			call ntc_rj_scan
			jp c, ntc_rj_part
			ld b, a
			ld a, (ntc_rj_want)
			ld e, a
			ld d, 0
			ld hl, ntc_rj_slots
			add hl, de
			ld (hl), b
			inc a
			jr ntc_rj_more
ntc_rj_all:
			ld a, (ntc_rj_slots)
			ld c, a
			call #B90F		; KL ROM SELECT: the main ROM
			di					; (KL ROM SELECT lets interrupts in)
			ld a, (ntc_rj_slots)	; its slot
			ld hl, ntc_rj_block
			ld bc, NTC_RJ_N
			ld de, ntc_rj_slots
ntc_rj_call:
			call 0				; HL = jump block, BC = entries, A = slot, DE = slots; C: DE = a number it hasn't got
			jp c, ntc_rj_lacks
			IF (ntc_bss >= 32768) && (ntc_bssfrom <= 16384)	; fwdref-ok
			ld hl, ntc_bssfrom		; (the end of the program - or this start code, which tables may go over)
			ELSE
			ld hl, ntc_free
			ENDIF
			ld (ntc_v_free), hl
			ld hl, ntc_start
			ld (ntc_v_start), hl
			ld hl, 0
			ld (ntc_v_stamp), hl
			ld a, 1
			ld (ntc_v_romen), a
			ld a, (ntc_rj_old)
			ld (ntc_v_romold), a
			or a				; NC: ready
			ret
; ntc_rj_scan - a ROM of the set: ROM ntc_rj_want (0 = the main one, any stamp; the others
; with the main one's stamp). NC: A = its slot, HL = past its block's count byte (the main
; one: at its patcher), it is selected. C: not there
ntc_rj_scan:
			ld c, 0
ntc_rj_next:
			push bc
			call #B90F		; KL ROM SELECT: ROM C
			pop bc
			ld a, (#C000)
			cp 1				; a background ROM?
			jr nz, ntc_rj_skip
			ld hl, (#C004)		; its names
			ld a, h
			cp #C0
			jr c, ntc_rj_skip
ntc_rj_name:
			ld a, (hl)
			inc hl
			or a
			jr nz, ntc_rj_name		; to the 0 after the names
			ld de, ntc_rj_sig
			ld b, ntc_rj_sige - ntc_rj_sig
ntc_rj_cmp:
			ld a, (de)
			cp (hl)
			jr nz, ntc_rj_skip
			inc de
			inc hl
			djnz ntc_rj_cmp
			ld e, (hl)
			inc hl
			ld d, (hl)			; DE = its set's stamp
			inc hl
			ld a, (ntc_rj_want)
			cp (hl)				; its place in the set
			jr nz, ntc_rj_skip
			or a
			jr z, ntc_rj_got
			push hl
			ld hl, (ntc_rj_set)
			or a
			sbc hl, de
			pop hl
			jr nz, ntc_rj_skip		; another build's
ntc_rj_got:
			ld (ntc_rj_set), de
			inc hl
			ld a, (hl)
			ld (ntc_rj_n), a		; ROMs in the set
			inc hl
			ld a, c
			or a				; NC
			ret
ntc_rj_skip:
			inc c
			ld a, c
			cp 32
			jr c, ntc_rj_next
			scf					; C: not there
			ret
ntc_rj_nf:
			ld hl, ntc_rj_tnf
			jr ntc_rj_fail
ntc_rj_part:				; a ROM of the set is missing: its number (1 = the main one)
			ld a, (ntc_rj_want)
			inc a
			ld e, a
			ld d, 0
			ld (ntc_rj_num), de
			ld hl, ntc_rj_tpt
			jr ntc_rj_fnum
ntc_rj_lacks:
			ld (ntc_rj_num), de
			ld hl, ntc_rj_tlk
ntc_rj_fnum:
			ld a, 1
			ld (ntc_rj_pn), a		; the number after the message
ntc_rj_fail:
			push hl
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT: the caller's selection again
			pop hl
			call ntc_rj_puts
			ld a, (ntc_rj_pn)
			or a
			jr z, ntc_rj_nl
			ld a, (ntc_rj_num + 1)
			call ntc_rj_hex
			ld a, (ntc_rj_num)
			call ntc_rj_hex
ntc_rj_nl:
			ld hl, ntc_rj_tnl
			call ntc_rj_puts
			ei
			call #BB06		; KM WAIT CHAR: a key first (a RUN" program's return resets the machine)
			di
			scf
			ret
ntc_rj_puts:				; HL = text, 0 ends; DE = its start
			ld d, h
			ld e, l
ntc_rj_pl:
			ld a, (hl)
			or a
			ret z
			call #BB5A		; TXT OUTPUT
			inc hl
			jr ntc_rj_pl
ntc_rj_hex:
			push af
			rrca
			rrca
			rrca
			rrca
			call ntc_rj_dig
			pop af
ntc_rj_dig:
			and 15
			add a, #90
			daa
			adc a, #40
			daa
			jp #BB5A
ntc_rj_num:		dw 0
ntc_rj_pn:		db 0			; 1 = a number goes after the message
ntc_rj_want:	db 0			; the ROM of the set looked for
ntc_rj_n:		db 1			; ROMs in the set
ntc_rj_set:		dw 0			; the set's stamp
ntc_rj_slots:	ds 8			; each ROM's slot, the main one first
ntc_rj_sig:		db "NTC", 2, "CPCFW", 0	; the ROMs' NTC block
ntc_rj_sige:
ntc_rj_tnf:		db "ROM NTC CPCFW (NTCFW.ROM) not found", 0
ntc_rj_tlk:		db "ROM NTC CPCFW too old: no routine #", 0
ntc_rj_tpt:		db "ROM NTCFW<n>.ROM not found: n = #", 0
ntc_rj_tnl:		db 13, 10, "Press a key", 13, 10, 0
ntc_rj_dropend:
ntc_rg428_e:
ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
			IF ntc_rj_dropend == ntc_end	; fwdref-ok
ntc_bssfrom	equ ntc_rj_drop		; the arrays over the start code (it has run)
			ELSE
ntc_bssfrom	equ ntc_end
			ENDIF
			IF (ntc_bssfrom < 32768) && (ntc_bssfrom + ntc_bss_size > 16384)	; fwdref-ok
ntc_bss		equ 32768		; after Option Reserve #4000-#7FFF
			ELSE
ntc_bss		equ ntc_bssfrom
			ENDIF
arr_bk		equ ntc_bss + 0		; 34 bytes
arr_sg		equ ntc_bss + 34		; 34 bytes
arr_st		equ ntc_bss + 68		; 34 bytes
arr_kq		equ ntc_bss + 102		; 34 bytes
arr_wp		equ ntc_bss + 136		; 34 bytes
arr_dm		equ ntc_bss + 170		; 34 bytes
arr_ra		equ ntc_bss + 204		; 34 bytes
arr_wk		equ ntc_bss + 238		; 34 bytes
arr_tn		equ ntc_bss + 272		; 34 bytes
arr_nb		equ ntc_bss + 306		; 34 bytes
arr_nc		equ ntc_bss + 340		; 34 bytes
arr_lt		equ ntc_bss + 374		; 34 bytes
arr_lb		equ ntc_bss + 408		; 34 bytes
arr_lc		equ ntc_bss + 442		; 34 bytes
arr_hyp_font		equ ntc_bss + 476		; 768 bytes
arr_ent_en		equ ntc_bss + 1244		; 12 bytes
ntc_bss_size	equ 1256
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
			IF ntc_free <= 32768	; fwdref-ok
ntc_memtab	equ 32768		; the Memory class's tables: above the window (Option Reserve)
			ELSE
ntc_memtab	equ ntc_free
			ENDIF
; Option Reserve: the program and its arrays (ntc_start .. ntc_free) must stay out of these
			ASSERT (ntc_free <= 16384) || (ntc_bss >= 32768), "the program (or its arrays) reaches into Option Reserve #4000-#7FFF (Main.bas line 21)"
			SAVEAMSDOS "CYBORGOS.BIN", ntc_start, ntc_end - ntc_start, ntc_start
